  const dislikes = new Set(profile?.preferences?.dislikes ?? []);
  const constraints = ledgerConstraints(data);
  const findings = profile ? findingExclusions(profile) : /* @__PURE__ */ new Map();
  const level2 = profile?.experience ? LEVEL_OF[profile.experience] : void 0;
  const memo = /* @__PURE__ */ new Map();
